import React, { useEffect, useRef, useState } from 'react';
import './App.css';

/* ── Reveal-on-scroll wrapper ────────────────────────────────────────────── */
function Reveal({ children, className = '', as: Tag = 'div', delay = 0 }) {
  const ref = useRef(null);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const obs = new IntersectionObserver(
      ([e]) => { if (e.isIntersecting) { el.style.transitionDelay = `${delay}ms`; el.classList.add('in'); } },
      { threshold: 0.18 }
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, [delay]);
  return <Tag ref={ref} className={`reveal ${className}`}>{children}</Tag>;
}

/* ── Nav ─────────────────────────────────────────────────────────────────── */
function Nav() {
  const [open, setOpen] = useState(false);
  return (
    <header className="nav">
      <a href="#top" className="nav__name">Emelinn Heikkinen</a>
      <nav className={`nav__menu ${open ? 'is-open' : ''}`}>
        <a href="#work" onClick={() => setOpen(false)}>Work</a>
        <a href="#about" onClick={() => setOpen(false)}>About</a>
        <a href="#book" onClick={() => setOpen(false)}>Book</a>
      </nav>
      <button className="nav__toggle mono" onClick={() => setOpen(o => !o)} aria-label="Menu">
        [ {open ? 'Close' : 'Menu'} ]
      </button>
    </header>
  );
}

/* ── Hero ────────────────────────────────────────────────────────────────── */
function Hero() {
  return (
    <section id="top" className="hero">
      <div className="hero__top">
        <span className="mono">Tattoo Artist</span>
        <span className="mono">Stockholm</span>
      </div>

      <h1 className="hero__title">
        <span className="hero__line">Emelinn —</span>
        <span className="hero__line hero__line--ital">Studio För Evigt.</span>
      </h1>

      <div className="hero__bottom">
        <p className="hero__lede">
          Minimalist and fine-line work, drawn for one body at a time.
          By appointment only.
        </p>
        <a href="#book" className="link-arrow">How to book <i>→</i></a>
      </div>
    </section>
  );
}

/* ── Line marks (minimal SVG) ────────────────────────────────────────────── */
const MARK = {
  a: (
    <svg viewBox="0 0 200 200" fill="none">
      <path d="M40 160 C40 160 60 90 100 70 C140 50 160 60 160 60" stroke="currentColor" strokeWidth="1" strokeLinecap="round"/>
      <path d="M100 70 C100 70 96 45 110 30 C124 15 140 22 138 38" stroke="currentColor" strokeWidth="1" strokeLinecap="round"/>
      <circle cx="100" cy="70" r="3" fill="currentColor"/>
    </svg>
  ),
  b: (
    <svg viewBox="0 0 200 200" fill="none">
      <circle cx="100" cy="100" r="60" stroke="currentColor" strokeWidth="1"/>
      <path d="M100 40 L100 160 M40 100 L160 100" stroke="currentColor" strokeWidth="0.6"/>
      <circle cx="100" cy="100" r="22" stroke="currentColor" strokeWidth="1"/>
    </svg>
  ),
  c: (
    <svg viewBox="0 0 200 200" fill="none">
      <path d="M60 170 C60 170 55 110 70 80 C85 50 100 45 100 45" stroke="currentColor" strokeWidth="1" strokeLinecap="round"/>
      <ellipse cx="80" cy="95" rx="18" ry="9" stroke="currentColor" strokeWidth="0.8" transform="rotate(-30 80 95)"/>
      <ellipse cx="120" cy="80" rx="20" ry="10" stroke="currentColor" strokeWidth="0.8" transform="rotate(25 120 80)"/>
      <path d="M100 45 C100 45 130 60 130 95" stroke="currentColor" strokeWidth="1" strokeLinecap="round"/>
    </svg>
  ),
  d: (
    <svg viewBox="0 0 200 200" fill="none">
      <ellipse cx="100" cy="100" rx="70" ry="38" stroke="currentColor" strokeWidth="1"/>
      <circle cx="100" cy="100" r="20" stroke="currentColor" strokeWidth="1"/>
      <circle cx="100" cy="100" r="8" fill="currentColor"/>
    </svg>
  ),
  e: (
    <svg viewBox="0 0 200 200" fill="none">
      <line x1="100" y1="30" x2="100" y2="170" stroke="currentColor" strokeWidth="1"/>
      <path d="M100 90 C100 90 75 80 65 60 M100 110 C100 110 125 100 135 80 M100 130 C100 130 80 122 72 105" stroke="currentColor" strokeWidth="0.8" strokeLinecap="round"/>
    </svg>
  ),
  f: (
    <svg viewBox="0 0 200 200" fill="none">
      <path d="M50 150 L100 50 L150 150" stroke="currentColor" strokeWidth="1" strokeLinejoin="round"/>
      <path d="M70 150 L100 90 L130 150" stroke="currentColor" strokeWidth="0.6"/>
      <circle cx="100" cy="120" r="4" stroke="currentColor" strokeWidth="0.8"/>
    </svg>
  ),
};

const PIECES = [
  { id: '01', title: 'Fine line', style: 'Fine line', year: '2024', mark: 'a' },
  { id: '02', title: 'Botanical', style: 'Geometric', year: '2024', mark: 'b' },
  { id: '03', title: 'Leaves', style: 'Single needle', year: '2023', mark: 'c' },
  { id: '04', title: 'Blackwork', style: 'Fine line', year: '2024', mark: 'd' },
  { id: '05', title: 'Flower', style: 'Botanical', year: '2023', mark: 'e' },
  { id: '06', title: 'Title', style: 'Blackwork', year: '2024', mark: 'f' },
];

/* ── Work (horizontal scroll gallery) ─────────────────────────────────────── */
function Work() {
  return (
    <section id="work" className="work">
      <Reveal className="sec-head">
        <span className="mono sec-head__tag">Selected work</span>
        <span className="mono sec-head__count">{String(PIECES.length).padStart(2, '0')} pieces</span>
      </Reveal>

      <div className="work__strip">
        {PIECES.map((p, i) => (
          <Reveal as="div" key={p.id} className="work__card" delay={i * 60}>
            <div className="work__card-frame">
              <span className="mono work__card-index">({p.id})</span>
              {MARK[p.mark]}
            </div>
            <div className="work__card-cap">
              <span className="work__card-title">{p.title}</span>
              <span className="mono work__card-meta">{p.style} — {p.year}</span>
            </div>
          </Reveal>
        ))}
      </div>
    </section>
  );
}

/* ── About ───────────────────────────────────────────────────────────────── */
function About() {
  return (
    <section id="about" className="about">
      <Reveal className="sec-head">
        <span className="mono sec-head__tag">About</span>
      </Reveal>

      <div className="about__body">
        <Reveal as="p" className="about__statement">
          I tattoo quietly — no flash, no walk-ins. Every piece is
          drawn for the person wearing it.
        </Reveal>

        <div className="about__cols">
          <Reveal className="about__col" delay={60}>
            <span className="about__col-label mono">Practice</span>
            <p>
              Fine-line and minimalist work, based at Studio För Evigt
              in Västertorp, Stockholm.
            </p>
          </Reveal>
          <Reveal className="about__col" delay={120}>
            <span className="about__col-label mono">Approach</span>
            <p>
              Bring an idea or a reference — every design is sketched
              from scratch to fit your body and your story.
            </p>
          </Reveal>
          <Reveal className="about__col" delay={180}>
            <span className="about__col-label mono">Details</span>
            <p>
              By appointment only.<br />
              <span className="placeholder">[ waitlist length ]</span><br />
              <span className="placeholder">[ minimum price ]</span>
            </p>
          </Reveal>
        </div>
      </div>
    </section>
  );
}

/* ── Process ─────────────────────────────────────────────────────────────── */
const STEPS = [
  { n: '01', t: 'Get in touch', d: 'Message with your idea, placement and size — via Instagram or email.' },
  { n: '02', t: 'Design', d: 'A sketch is drawn for your piece. You review it before the session.' },
  { n: '03', t: 'Deposit', d: 'A deposit secures your appointment slot.' },
  { n: '04', t: 'Session', d: 'Come in, get tattooed. Aftercare guidance is included.' },
];
function Process() {
  return (
    <section className="process">
      <Reveal className="sec-head">
        <span className="mono sec-head__tag">How it works</span>
      </Reveal>
      <ol className="process__list">
        {STEPS.map((s, i) => (
          <Reveal as="li" key={s.n} className="process__item" delay={i * 70}>
            <span className="process__n mono">{s.n}</span>
            <div className="process__text">
              <h3>{s.t}</h3>
              <p>{s.d}</p>
            </div>
          </Reveal>
        ))}
      </ol>
    </section>
  );
}

/* ── Book (informational — no form) ───────────────────────────────────────── */
function Book() {
  return (
    <section id="book" className="book">
      <div className="book__intro">
        <h2 className="book__title">
          Let's make<br /><span className="ital">something.</span>
        </h2>
        <p className="book__note mono">
          Bookings are handled directly over Instagram or email —
          no form, just send a message.
        </p>
      </div>

      <div className="book__contact">
        <a
          href="https://www.instagram.com/emelinn"
          className="book__contact-row"
          target="_blank"
          rel="noreferrer"
        >
          <span className="mono">Instagram</span>
          <span className="book__contact-value">@emelinn <i>→</i></span>
        </a>
        <a href="mailto:emelinnemelinn@gmail.com" className="book__contact-row">
          <span className="mono">Email</span>
          <span className="book__contact-value">emelinnemelinn@gmail.com <i>→</i></span>
        </a>
      </div>
    </section>
  );
}

/* ── Footer ──────────────────────────────────────────────────────────────── */
function Footer() {
  return (
    <footer className="footer">
      <span>Emelinn Heikkinen</span>
      <span className="mono">Stockholm</span>
      <span className="mono">© {new Date().getFullYear()}</span>
    </footer>
  );
}

export default function App() {
  return (
    <>
      <Nav />
      <main>
        <Hero />
        <Work />
        <About />
        <Process />
        <Book />
      </main>
      <Footer />
    </>
  );
}
